import{_ as e,c as a,a0 as i,o as t}from"./chunks/framework.BGabeMLJ.js";const g=JSON.parse('{"title":"Requesting a Master Image","description":"","frontmatter":{},"headers":[],"relativePath":"guide/user/master-images.md","filePath":"guide/user/master-images.md"}'),n={name:"guide/user/master-images.md"};function l(o,s,r,h,p,d){return t(),a("div",null,s[0]||(s[0]=[i(`<h1 id="requesting-a-master-image" tabindex="-1">Requesting a Master Image <a class="header-anchor" href="#requesting-a-master-image" aria-label="Permalink to &quot;Requesting a Master Image&quot;">​</a></h1><p>A <strong>master image</strong> is the container image your analysis code is built on. It provides the runtime (e.g. Python) and all software dependencies. Packages cannot be installed while an analysis runs, so every library your script imports has to be part of the master image you select when <a href="/guide/user/analysis.html">creating the analysis</a>.</p><p>All master images are maintained in the public <a href="https://github.com/PrivateAIM/master-images" target="_blank" rel="noreferrer">PrivateAIM/master-images</a> repository. If none of them fits, you request a new one with a pull request. This page describes that process:</p><ol><li><a href="#_1-check-the-existing-master-images">Check whether a suitable image already exists</a></li><li><a href="#_2-create-your-master-image">Create your own master image</a></li><li><a href="#_3-test-the-image-locally">Test it locally</a></li><li><a href="#_4-open-a-pull-request">Open a pull request</a></li><li><a href="#_5-synchronize-the-hub">Synchronize the Hub</a></li></ol><h2 id="_1-check-the-existing-master-images" tabindex="-1">1. Check the existing master images <a class="header-anchor" href="#_1-check-the-existing-master-images" aria-label="Permalink to &quot;1. Check the existing master images&quot;">​</a></h2><p>Please check first whether a master image already contains the dependencies you need. Every image is a folder below <a href="https://github.com/PrivateAIM/master-images/tree/master/data" target="_blank" rel="noreferrer"><code>data/</code></a> in the repository, and its <code>requirements.txt</code> lists the installed packages.</p><table tabindex="0"><thead><tr><th>Location</th><th>Contains</th><th>Examples</th></tr></thead><tbody><tr><td><code>data/python/</code></td><td>general purpose Python images</td><td><code>base</code>, <code>ml</code>, <code>pytorch</code>, <code>tensorflow</code>, <code>genomics</code></td></tr><tr><td><code>data/python/use-cases/</code></td><td>images built for a specific project or analysis</td><td><code>fedstats</code>, <code>gemtex</code>, <code>record-linkage</code></td></tr><tr><td><code>data/python/conda/</code></td><td>images based on a conda environment</td><td><code>fed-gwas</code></td></tr><tr><td><code>data/r/</code></td><td>R images</td><td><code>ml</code></td></tr></tbody></table><p>The same images are offered in the Hub in the <strong>Image</strong> tab of the analysis wizard.</p><p>If an existing image only lacks one or two packages, consider proposing to extend it instead of adding a new one.</p><h2 id="_2-create-your-master-image" tabindex="-1">2. Create your master image <a class="header-anchor" href="#_2-create-your-master-image" aria-label="Permalink to &quot;2. Create your master image&quot;">​</a></h2><p>Create a new branch in the <a href="https://github.com/PrivateAIM/master-images" target="_blank" rel="noreferrer">master-images</a> repository. If you do not have write access, fork the repository first.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/PrivateAIM/master-images.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> master-images</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add-my-analysis-image</span></span></code></pre></div><p>Then:</p><ol><li><strong>Create a new folder</strong> named after your master image, e.g. <code>data/python/use-cases/my-analysis/</code>. The folder name becomes the name of the image.</li><li><strong>Copy the <code>Dockerfile</code> and <code>requirements.txt</code></strong> of one of the examples into it, e.g. from <code>fedstats</code>, <code>gemtex</code> or <code>pytorch</code>. Pick the one closest to what you need: <code>fedstats</code> and <code>gemtex</code> start from a plain Python image, <code>pytorch</code> from an NVIDIA CUDA image for GPU workloads.</li><li><strong>Adjust <code>requirements.txt</code></strong> to the dependencies your analysis script requires.</li></ol><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/python/use-cases/my-analysis</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/python/use-cases/fedstats/Dockerfile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   data/python/use-cases/fedstats/requirements.txt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   data/python/use-cases/my-analysis/</span></span></code></pre></div><p>The resulting folder looks like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data/python/use-cases/my-analysis/</span></span>
<span class="line"><span>├── Dockerfile</span></span>
<span class="line"><span>├── requirements.txt</span></span>
<span class="line"><span>└── README.md</span></span></code></pre></div><p>The <code>README.md</code> is optional and holds one or two sentences on what the image is for.</p><p><code>requirements.txt</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pandas == 2.2.3</span></span>
<span class="line"><span>numpy == 1.26.4</span></span>
<span class="line"><span>scikit-learn == 1.6.1</span></span></code></pre></div><p><code>Dockerfile</code> (copied from <code>fedstats</code>):</p><div class="language-dockerfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> python:3.13</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ARG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DEBIAN_FRONTEND=noninteractive</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> apt-get update -yqq &amp;&amp; \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    apt-get dist-upgrade -yqq &amp;&amp; \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    apt-get install -yqq git</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> requirements.txt /tmp/requirements.txt</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> python3 -m pip install --upgrade pip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pip3 install -r /tmp/requirements.txt</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pip3 install \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    git+https://github.com/PrivateAIM/python-sdk-patterns.git@1.0.0</span></span></code></pre></div><p>A few rules:</p><ul><li><strong>Keep the last instruction.</strong> It installs the FLAME SDK and patterns (<code>flame</code>). Without it your analysis cannot start. Use the same version as the example you copied from.</li><li><strong>Pin every version</strong> (<code>package == x.y.z</code>), so the image builds reproducibly and can be reviewed.</li><li><strong>Do not list <code>flamesdk</code> dependencies in conflicting versions.</strong> The SDK requires specific ranges of <code>httpx</code>, <code>fastapi</code> and <code>uvicorn</code>. If you need them, copy the versions from the example.</li><li><strong>System packages or command line tools</strong> are added with a further <code>apt-get install</code> in the <code>Dockerfile</code>.</li><li><strong>No data, credentials or analysis code</strong> belong in the image. The repository and the images are public, and your code is added later by the Hub.</li></ul><p>The image group (<code>python</code>) and the start command (<code>python -u</code>) are inherited from the <code>image-group.json</code> of the parent folder, so you do not need to configure them.</p><h2 id="_3-test-the-image-locally" tabindex="-1">3. Test the image locally <a class="header-anchor" href="#_3-test-the-image-locally" aria-label="Permalink to &quot;3. Test the image locally&quot;">​</a></h2><p>Test before you open the pull request. A failed build, or an import error that only shows up on a node, costs everybody a full review and approval round. You need <a href="https://docs.docker.com/get-docker/" target="_blank" rel="noreferrer">Docker</a>.</p><p><strong>Build the image:</strong></p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-analysis:test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/python/use-cases/my-analysis</span></span></code></pre></div><p><strong>Check that your dependencies are importable</strong>, including <code>flame</code>:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-analysis:test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import flame, pandas, sklearn; print(&#39;ok&#39;)&quot;</span></span></code></pre></div><p><strong>Run your analysis in the image.</strong> Write a local test script for your analysis with <code>StarModelTester</code> as described in <a href="/guide/user/local-testing.html">Local Testing</a>, then execute it inside the container instead of your own Python environment:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;:/work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /work</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-analysis:test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_analysis_test.py</span></span></code></pre></div><p>Run this from the folder that contains your script and test data. If it runs through, your script works with exactly the package versions the nodes will use.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The repository also ships a small CLI that builds an image the same way the CI does:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python/use-cases/my-analysis</span></span></code></pre></div></div><h2 id="_4-open-a-pull-request" tabindex="-1">4. Open a pull request <a class="header-anchor" href="#_4-open-a-pull-request" aria-label="Permalink to &quot;4. Open a pull request&quot;">​</a></h2><p>Commit the new folder, push your branch and open a pull request against the <code>master</code> branch of <a href="https://github.com/PrivateAIM/master-images/pulls" target="_blank" rel="noreferrer">PrivateAIM/master-images</a>.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/python/use-cases/my-analysis</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;feat: add my-analysis master image&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add-my-analysis-image</span></span></code></pre></div><p>Describe in the pull request which analysis or project the image is for and why no existing image fits. A maintainer reviews the change.</p><p>After the pull request has been approved and merged, a worker automatically builds the new master image and pushes it to the Hub&#39;s Harbor registry. You do not have to build or push anything yourself.</p><h2 id="_5-synchronize-the-hub" tabindex="-1">5. Synchronize the Hub <a class="header-anchor" href="#_5-synchronize-the-hub" aria-label="Permalink to &quot;5. Synchronize the Hub&quot;">​</a></h2><p>The Hub has to learn about the new image once:</p><ol><li>In the Hub UI, go to <strong>Admin → General → Services → Master Images</strong>.</li><li>Press the green <strong>Sync</strong> button.</li></ol><p>After a few minutes, the newly built master image is available for selection in projects and analyses.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Synchronizing requires the <code>MASTER_IMAGE_MANAGE</code> permission. If you do not see the page or the button, ask a Hub administrator to trigger the synchronization for you.</p></div><p>You can now select the image in the <strong>Image</strong> tab when <a href="/guide/user/analysis.html#_3-configure-analysis">creating an analysis</a>.</p><h2 id="updating-an-existing-master-image" tabindex="-1">Updating an existing master image <a class="header-anchor" href="#updating-an-existing-master-image" aria-label="Permalink to &quot;Updating an existing master image&quot;">​</a></h2><p>To add or upgrade a package in an image that already exists, follow the same steps: change its <code>requirements.txt</code> or <code>Dockerfile</code> on a branch, test locally, open a pull request and synchronize the Hub after the merge. Keep in mind that other analyses may use the same image.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>Likely cause</th><th>What to do</th></tr></thead><tbody><tr><td><code>docker build</code> fails in <code>pip3 install -r</code></td><td>version does not exist, or conflicts with another package</td><td>fix the pin, and check the Python version in <code>FROM</code></td></tr><tr><td><code>ModuleNotFoundError: flame</code></td><td>the <code>python-sdk-patterns</code> line was removed</td><td>restore the last instruction of the <code>Dockerfile</code></td></tr><tr><td>Image does not appear in the Hub</td><td>not synchronized yet, or the build is still running</td><td>press <strong>Sync</strong> again after a few minutes</td></tr><tr><td>Analysis fails with <code>ModuleNotFoundError</code> on the node</td><td>package missing in <code>requirements.txt</code></td><td>add it, and repeat the local test</td></tr></tbody></table>`,50)]))}const k=e(n,[["render",l]]);export{g as __pageData,k as default};
